-- ============================================================================
-- Migration 1109: the Sheet Metal - Hydroforming machines -- press rates and forming time, blanking press data, and India
-- ============================================================================
-- Generated by scripts/generate-hydroforming-machines-migration.js; re-run it and diff instead of editing.
--
-- Migration 828 loaded the 38 hydroform presses (memory/Sheetmetal Hydroforming/Machine/machines_hydroform.csv) with no rate and no labour (the USA
-- file has neither) and no forming time, so a hydroformed part could not be priced; and no machine of the group for India.
--
-- 1. The 38 USA hydroform presses: direct and indirect overhead (USD/hr, to cents) from memory/Countries data/Netherlands_XML_Data_.csv, the closest
--    export to the USA file (no export lists the USA; on the 18 blanking presses both rate, the largest difference is
--    8.88 USD/hr, United Power SHD-666 Ton), labour 3 - Metal 36.30 USD/hr (the rate that grade's HR Rates rows carry), and specs
--    machine_forming_cycle_time_s, the press's forming cycle (the exports' machineFormingCycleTime, s; the same in all 14 exports).
--    Rates are written only where the press has none, so a rate entered in HR Rates is kept.
-- 2. The 18 USA offline blanking presses: specs press_cycle_time_s, mass_coeff_handling_time_s_per_kg, const_coeff_handling_time_s, max_part_length_mm, max_part_width_mm, pitch_margin_mm, side_margin_mm, trim_strip_mm, shut_height_mm (the exports' stroke and handling data,
--    the same in every export).
-- 3. India: the twins of all 56 (memory/Countries data/India_XML_Data_.csv, commodity "Sheet Metal - Hydroforming"): each machine's own overheads and labour
--    3 - Metal India 1.73 USD/hr; specs as the USA twin's, with the India rate basis.
--
-- Idempotent. Verify:
--   SELECT location, machine_class, count(*), count(*) FILTER (WHERE mhr_usd_per_hour > 0) FROM mhr_records
--   WHERE process_group = 'Sheet Metal - Hydroforming' GROUP BY 1, 2 ORDER BY 1, 2;
-- ============================================================================

UPDATE mhr_records m SET
  specs = COALESCE(m.specs, '{}'::jsonb) || jsonb_build_object('machine_forming_cycle_time_s', v.fct, 'rate_basis', $str$overheads memory/Countries data/Netherlands_XML_Data_.csv (no export lists the USA); labour 3 - Metal USA 36.30$str$),
  updated_at = now()
FROM (VALUES
  ($str$Hydroform Press - Deep Draw - 456 Dia$str$, 45::numeric),
  ($str$Hydroform Press - Deep Draw - 630 Dia$str$, 61::numeric),
  ($str$Hydroform Press - Deep Draw - 838 Dia$str$, 65::numeric),
