DO $hydroforming_machines$
DECLARE
  cols text; sel text; r record; src_id uuid; n integer := 0; missing text[] := '{}';
BEGIN
  SELECT
    string_agg(quote_ident(c.column_name), ', ' ORDER BY c.ordinal_position),
    string_agg(
      CASE c.column_name
        WHEN 'location'                                THEN '$5'
        WHEN 'country_code'                            THEN '$6'
        WHEN 'direct_overhead_rate'                    THEN '$2'
        WHEN 'indirect_overhead_rate'                  THEN '$3'
        WHEN 'benchmark_direct_overhead_rate_usd_hr'   THEN '$2'
        WHEN 'benchmark_indirect_overhead_rate_usd_hr' THEN '$3'
        WHEN 'total_machine_hour_rate'                 THEN 'ROUND(($2 + $3)::numeric, 2)'
        WHEN 'mhr_usd_per_hour'                        THEN 'ROUND(($2 + $3)::numeric, 2)'
        WHEN 'usd_labor_rate_per_hr'                   THEN '$4'
        WHEN 'usd_lhr_total'                           THEN '$4'
        WHEN 'benchmark_labor_rate_usd_hr'             THEN '$4'
        WHEN 'benchmark_source_key'                    THEN '$7'
        WHEN 'id'                                      THEN 'gen_random_uuid()'
        WHEN 'created_at'                              THEN 'now()'
        WHEN 'updated_at'                              THEN 'now()'
        ELSE 'src.' || quote_ident(c.column_name)
      END, ', ' ORDER BY c.ordinal_position
    )
  INTO cols, sel
  FROM information_schema.columns c
  WHERE c.table_schema = 'public' AND c.table_name = 'mhr_records' AND c.is_generated = 'NEVER';

  -- (location, country, machine class, machine name, labour, direct overhead, indirect overhead, source key), USD/hr
  FOR r IN SELECT * FROM (VALUES
    ($str$India$str$, $str$IN$str$, $str$hydroform_offline_blank$str$, $str$Bliss - B-55$str$, 1.73, 62.45, 4.11, $str$Offline Blank:Bliss - B-55:India$str$),
    ($str$India$str$, $str$IN$str$, $str$hydroform_offline_blank$str$, $str$Default Press$str$, 1.73, 22.61, 4.11, $str$Offline Blank:Default Press:India$str$),
    ($str$India$str$, $str$IN$str$, $str$hydroform_offline_blank$str$, $str$Niagara - E511B$str$, 1.73, 77.48, 4.11, $str$Offline Blank:Niagara - E511B:India$str$),
    ($str$India$str$, $str$IN$str$, $str$hydroform_offline_blank$str$, $str$Offline Blank Press - 1,500kN Press Force$str$, 1.73, 13.42, 4.11, $str$Offline Blank:Offline Blank Press - 1,500kN Press Force:India$str$),
    ($str$India$str$, $str$IN$str$, $str$hydroform_offline_blank$str$, $str$Offline Blank Press - 10,000kN Press Force$str$, 1.73, 85.18, 4.11, $str$Offline Blank:Offline Blank Press - 10,000kN Press Force:India$str$),
    ($str$India$str$, $str$IN$str$, $str$hydroform_offline_blank$str$, $str$Offline Blank Press - 3,000kN Press Force$str$, 1.73, 29.22, 4.11, $str$Offline Blank:Offline Blank Press - 3,000kN Press Force:India$str$),
    ($str$India$str$, $str$IN$str$, $str$hydroform_offline_blank$str$, $str$Offline Blank Press - 5,000kN Press Force$str$, 1.73, 47.44, 4.11, $str$Offline Blank:Offline Blank Press - 5,000kN Press Force:India$str$),
    ($str$India$str$, $str$IN$str$, $str$hydroform_offline_blank$str$, $str$Offline Blank Press - 7,000kN Press Force$str$, 1.73, 63.24, 4.11, $str$Offline Blank:Offline Blank Press - 7,000kN Press Force:India$str$),
    ($str$India$str$, $str$IN$str$, $str$hydroform_offline_blank$str$, $str$Schuler 1150 Ton$str$, 1.73, 58.82, 4.11, $str$Offline Blank:Schuler 1150 Ton:India$str$),
    ($str$India$str$, $str$IN$str$, $str$hydroform_offline_blank$str$, $str$Schuler A2/200 - 360$str$, 1.73, 42.44, 4.11, $str$Offline Blank:Schuler A2/200 - 360:India$str$),
    ($str$India$str$, $str$IN$str$, $str$hydroform_offline_blank$str$, $str$United Power SHD-220 Ton$str$, 1.73, 21.21, 4.11, $str$Offline Blank:United Power SHD-220 Ton:India$str$),
    ($str$India$str$, $str$IN$str$, $str$hydroform_offline_blank$str$, $str$United Power SHD-400 Ton$str$, 1.73, 37.86, 4.11, $str$Offline Blank:United Power SHD-400 Ton:India$str$),
    ($str$India$str$, $str$IN$str$, $str$hydroform_offline_blank$str$, $str$United Power SHD-666 Ton$str$, 1.73, 64.01, 4.11, $str$Offline Blank:United Power SHD-666 Ton:India$str$),
    ($str$India$str$, $str$IN$str$, $str$hydroform_offline_blank$str$, $str$United Power SHS-166 Ton$str$, 1.73, 15.59, 4.11, $str$Offline Blank:United Power SHS-166 Ton:India$str$),
    ($str$India$str$, $str$IN$str$, $str$hydroform_offline_blank$str$, $str$United Power SHS-666 Ton$str$, 1.73, 63.68, 4.11, $str$Offline Blank:United Power SHS-666 Ton:India$str$),
