    ($str$India$str$, $str$IN$str$, $str$hydroform$str$, $str$Hydroform Press - Deep Draw - 456 Dia$str$, 1.73, 51.38, 2.64, $str$Hydroform:Hydroform Press - Deep Draw - 456 Dia:India$str$),
    ($str$India$str$, $str$IN$str$, $str$hydroform$str$, $str$Hydroform Press - Deep Draw - 630 Dia$str$, 1.73, 63.12, 1.19, $str$Hydroform:Hydroform Press - Deep Draw - 630 Dia:India$str$),
