    ($str$India$str$, $str$IN$str$, $str$hydroform$str$, $str$Triform 16-10-7BD$str$, 1.73, 48.58, 1.03, $str$Hydroform:Triform 16-10-7BD:India$str$),
    ($str$India$str$, $str$IN$str$, $str$hydroform$str$, $str$Triform 20-10-10BD$str$, 1.73, 61.35, 1.14, $str$Hydroform:Triform 20-10-10BD:India$str$),
    ($str$India$str$, $str$IN$str$, $str$hydroform$str$, $str$Triform 25-10-12BD$str$, 1.73, 76.97, 1.3, $str$Hydroform:Triform 25-10-12BD:India$str$),
    ($str$India$str$, $str$IN$str$, $str$hydroform$str$, $str$Triform 32-10-12BD$str$, 1.73, 110.67, 1.52, $str$Hydroform:Triform 32-10-12BD:India$str$),
    ($str$India$str$, $str$IN$str$, $str$hydroform$str$, $str$Triform 42-10-12BD$str$, 1.73, 168.37, 1.71, $str$Hydroform:Triform 42-10-12BD:India$str$)
  ) AS v(location, country, machine_class, machine_name, labor, direct, indirect, source_key)
  LOOP
    SELECT id INTO src_id FROM mhr_records
    WHERE process_group = $str$Sheet Metal - Hydroforming$str$ AND location = 'USA' AND machine_class = r.machine_class AND machine_name = r.machine_name
    LIMIT 1;
    IF src_id IS NULL THEN
      missing := array_append(missing, r.machine_class || ':' || r.machine_name);
      CONTINUE;
    END IF;
    IF EXISTS (SELECT 1 FROM mhr_records m WHERE m.location = r.location AND m.machine_class = r.machine_class AND m.machine_name = r.machine_name) THEN
      CONTINUE;
    END IF;
    EXECUTE format('INSERT INTO mhr_records (%s) SELECT %s FROM mhr_records src WHERE src.id = $1', cols, sel)
      USING src_id, r.direct, r.indirect, r.labor, r.location, r.country, r.source_key;
    n := n + 1;
  END LOOP;

  RAISE NOTICE '% twins inserted: %', $str$Sheet Metal - Hydroforming$str$, n;
  IF array_length(missing, 1) > 0 THEN
    RAISE NOTICE '% twins with no USA row (not inserted): %', $str$Sheet Metal - Hydroforming$str$, missing;
  END IF;
END $hydroforming_machines$;

UPDATE mhr_records SET specs = specs || jsonb_build_object('rate_basis', CASE machine_class
    WHEN $str$hydroform$str$ THEN $str$overheads memory/Countries data/India_XML_Data_.csv; labour 3 - Metal India 1.73$str$
    ELSE $str$overheads memory/Countries data/India_XML_Data_.csv; labour 3 - Metal India 1.73$str$ END), updated_at = now()
WHERE process_group = $str$Sheet Metal - Hydroforming$str$ AND location = 'India' AND specs IS NOT NULL
  AND specs ->> 'rate_basis' IS DISTINCT FROM CASE machine_class WHEN $str$hydroform$str$ THEN $str$overheads memory/Countries data/India_XML_Data_.csv; labour 3 - Metal India 1.73$str$ ELSE $str$overheads memory/Countries data/India_XML_Data_.csv; labour 3 - Metal India 1.73$str$ END;

DO $hydroforming_check$
DECLARE bad text[]; n integer;
BEGIN
  SELECT array_agg(location || ': ' || machine_name ORDER BY location, machine_name) INTO bad FROM mhr_records
   WHERE process_group = $str$Sheet Metal - Hydroforming$str$ AND machine_class = $str$hydroform$str$ AND location IN ('USA', 'India')
     AND NOT (COALESCE(mhr_usd_per_hour, 0) > 0 AND COALESCE(usd_labor_rate_per_hr, 0) > 0 AND COALESCE((specs ->> 'machine_forming_cycle_time_s')::numeric, 0) > 0);
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'Hydroform presses without a rate, labour or forming time: %', bad; END IF;
  SELECT array_agg(location || ': ' || machine_name ORDER BY location, machine_name) INTO bad FROM mhr_records
   WHERE process_group = $str$Sheet Metal - Hydroforming$str$ AND machine_class = $str$hydroform_offline_blank$str$ AND location IN ('USA', 'India')
     AND NOT COALESCE((specs ->> 'press_cycle_time_s')::numeric, 0) > 0;
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'Offline blanking presses without a press cycle time: %', bad; END IF;
  SELECT count(*) INTO n FROM mhr_records WHERE process_group = $str$Sheet Metal - Hydroforming$str$ AND location = 'India' AND machine_class IN ($str$hydroform$str$, $str$hydroform_offline_blank$str$);
  IF n <> 56 THEN RAISE EXCEPTION 'expected 56 India Sheet Metal - Hydroforming machines, found %', n; END IF;
END $hydroforming_check$;

